using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
public static class StairALabels {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";
 static void Add(string name,Transform group,Vector3 p,float yaw,Material mat){var old=group.Find(name);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var g=new GameObject(name);g.transform.SetParent(group,false);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(0,yaw,0);var m=AssetDatabase.LoadAssetAtPath<Mesh>(E+"TC_LabelQuad.asset");g.AddComponent<MeshFilter>().sharedMesh=m;var rr=g.AddComponent<MeshRenderer>();rr.sharedMaterial=mat;rr.shadowCastingMode=ShadowCastingMode.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var t=root.Find("T02_StairA_Art/T02_Corridor");Func<string,Material> mat=c=>AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/ND_Label_"+c+".mat");Add("T02_VA_departure",t,new Vector3(1.15f,.014f,2.5f),0,mat("VA"));Add("T02_VA_arrival",t,new Vector3(1.15f,.014f,11.26f),0,mat("VA"));Add("T02_C02_departure",t,new Vector3(-1.15f,.014f,11.26f),180,mat("C02"));Add("T02_C01_return",t,new Vector3(-1.15f,.014f,3.8f),180,mat("C01"));Add("T01_VA_through",root.Find("T01_Corridor_Finish"),new Vector3(1.15f,.014f,6.73f),0,mat("VA"));EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{floorLabels=5};}
}
